{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Ensure the Azure SQL Database Namespace is zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database does not specify a zone redundancy configuration. For production workloads, enabling zone redundancy improves availability and resilience against single-zone failures."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"S0\"\n  tags = var.common_tags\n  zone_redundant = true\n}",
  "fix_summary": "Added `zone_redundant = true` to the `azurerm_mssql_database` resource to ensure high availability across multiple availability zones, addressing CKV_AZURE_229. The Ledger feature (CKV_AZURE_224) was not enabled as it requires specific compliance needs and additional setup (like `ledger_enabled` and potentially `short_term_retention_policy` adjustments or separate ledger resources depending on provider version/context), but zone redundancy is a standard best practice for general availability."
}
